-- Migration: Year 3 - Psychiatry - Substance Use Disorders MCQ Bank (1-300)
-- Based on Kaplan & Sadock's Synopsis 12th Ed, First Aid for the Psychiatry Clerkship 5th Ed, and MGH Pocket Psychiatry
-- Date: 2026-04-30

BEGIN;

DO $$ 
DECLARE 
    v_topic_id UUID;
BEGIN
    SELECT id INTO v_topic_id FROM topics WHERE slug = 'substance-use-disorders' LIMIT 1;

    DELETE FROM mcqs WHERE topic_id = v_topic_id;

    -- SECTION 1: General Substance Use Concepts & Alcohol (1-100)
    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '1: According to DSM-5, how is a Substance Use Disorder (SUD) classified?', '["By the amount of drug used", "A maladaptive pattern of substance use leading to clinically significant impairment or distress, measured by 11 criteria", "Only by physical dependence", "None"]', 1, 'Severity is based on the number of criteria met. (DSM-5)'),
    (v_topic_id, '2: How many criteria must be met to diagnose a MILD Substance Use Disorder?', '["1", "2-3", "4-5", "6+"]', 1, 'Mild (2-3), Moderate (4-5), Severe (6+). (DSM-5)'),
    (v_topic_id, '3: Which of the following is NOT one of the 11 DSM-5 criteria for SUD?', '["Tolerance", "Withdrawal", "Daily use of the substance", "Craving or a strong desire to use"]', 2, 'Daily use is not a criterion; impairment/loss of control is what matters. (First Aid)'),
    (v_topic_id, '4: What is "Tolerance"?', '["Needing markedly increased amounts of the substance to achieve intoxication or desired effect", "The physical symptoms when stopping", "The psychological desire to use", "None"]', 0, 'Or markedly diminished effect with continued use of the same amount. (Kaplan & Sadock)'),
    (v_topic_id, '5: What is "Withdrawal"?', '["The characteristic withdrawal syndrome for the substance, or using the substance to relieve withdrawal symptoms", "Craving", "Tolerance", "None"]', 0, 'A physiological dependence criterion. (MGH Pocket)'),
    (v_topic_id, '6: Is physical dependence (tolerance and withdrawal) sufficient to diagnose a Substance Use Disorder?', '["Yes", "No, if they are occurring in the context of appropriate medical treatment (e.g., prescribed opioids for cancer pain)", "Only for alcohol", "None"]', 1, 'Physical dependence alone does not equal addiction. (First Aid)'),
    (v_topic_id, '7: Which brain pathway is the primary reward circuit involved in all addictions?', '["Nigrostriatal pathway", "Mesolimbic dopamine pathway (VTA to Nucleus Accumbens)", "Tuberoinfundibular pathway", "Mesocortical pathway"]', 1, 'Drugs of abuse hijack this survival-reward system. (Kaplan & Sadock)'),
    (v_topic_id, '8: What is the most widely used psychoactive substance in the world?', '["Alcohol", "Caffeine", "Nicotine", "Cannabis"]', 1, 'Often not considered a "drug of abuse" clinically unless causing severe impairment. (MGH Pocket)'),
    (v_topic_id, '9: What is the most commonly abused illicit drug in the US?', '["Cocaine", "Heroin", "Cannabis (Marijuana)", "Methamphetamine"]', 2, 'Though legalization has shifted its legal status in many states. (First Aid)'),
    (v_topic_id, '10: Alcohol (Ethanol) primarily acts by:', '["Blocking dopamine", "Enhancing GABA-A receptor function (inhibitory) and inhibiting NMDA glutamate receptors (excitatory)", "Stimulating serotonin", "None"]', 1, 'A central nervous system depressant. (Kaplan & Sadock)'),
    (v_topic_id, '11: What is the standard drink size for wine in the US?', '["12 oz", "5 oz", "1.5 oz", "8 oz"]', 1, '12 oz beer = 5 oz wine = 1.5 oz liquor (80 proof). (MGH Pocket)'),
    (v_topic_id, '12: According to the NIAAA, what is considered "heavy drinking" or "at-risk drinking" for men?', '["1 drink per day", "More than 4 drinks on any day OR more than 14 drinks per week", "More than 10 drinks a day", "None"]', 1, 'Threshold for counseling/intervention. (First Aid)'),
    (v_topic_id, '13: What is "at-risk drinking" for women?', '["More than 4 drinks a day / 14 a week", "More than 3 drinks on any day OR more than 7 drinks per week", "More than 5 drinks a day", "None"]', 1, 'Women have lower gastric alcohol dehydrogenase activity and lower body water volume. (Kaplan & Sadock)'),
    (v_topic_id, '14: Which screening questionnaire is most widely used for alcohol misuse in primary care?', '["PHQ-9", "CAGE questionnaire", "MMSE", "CIWA"]', 1, 'Cut down, Annoyed, Guilty, Eye-opener. (MGH Pocket)'),
    (v_topic_id, '15: In the CAGE questionnaire, what does the "E" stand for?', '["Energy", "Eye-opener (drinking first thing in the morning to steady nerves or get rid of a hangover)", "Eating", "None"]', 1, 'A strong indicator of physical dependence. (First Aid)'),
    (v_topic_id, '16: Which biomarker is the MOST sensitive and specific for chronic heavy alcohol consumption?', '["AST", "Carbohydrate-deficient transferrin (CDT) or Phosphatidylethanol (PEth)", "ALT", "MCV"]', 1, 'PEth is highly specific and detects drinking over the past 2-4 weeks. (Kaplan & Sadock)'),
    (v_topic_id, '17: What is the classic liver enzyme ratio in alcoholic liver disease?', '["ALT > AST (2:1)", "AST > ALT (usually 2:1 or greater)", "Equal", "None"]', 1, '"ToAST to alcohol." (First Aid)'),
    (v_topic_id, '18: Macrocytosis (elevated MCV) in an alcoholic is most likely due to:', '["Iron deficiency", "Direct toxic effect of alcohol on bone marrow and Folate/B12 deficiency", "Kidney failure", "None"]', 1, 'A common lab finding. (MGH Pocket)'),
    (v_topic_id, '19: Alcohol intoxication clinically presents with:', '["Pinpoint pupils and respiratory depression", "Slurred speech, ataxia, incoordination, nystagmus, impaired memory/judgment", "Hyperthermia and rigidity", "None"]', 1, 'Can progress to stupor, coma, and death. (Kaplan & Sadock)'),
    (v_topic_id, '20: What is the legal blood alcohol concentration (BAC) limit for driving in most US states?', '["0.04%", "0.08%", "0.10%", "0.15%"]', 1, 'Though impairment begins at much lower levels. (First Aid)'),
    (v_topic_id, '21: A non-tolerant individual with a BAC of 0.40% is at risk for:', '["Mild euphoria", "Ataxia only", "Respiratory depression, coma, and death", "None"]', 2, 'Lethal dose for naive drinkers. (MGH Pocket)'),
    (v_topic_id, '22: Treatment for acute, severe alcohol intoxication (coma)?', '["Flumazenil", "Supportive care (airway, breathing), IV fluids, Thiamine, Folate", "Haloperidol", "None"]', 1, 'No specific pharmacological antidote exists for ethanol. (Kaplan & Sadock)'),
    (v_topic_id, '23: Why must Thiamine (Vitamin B1) be given BEFORE or WITH IV glucose in an alcoholic?', '["Glucose causes allergic reaction", "Glucose metabolism rapidly consumes remaining thiamine stores, potentially precipitating Wernicke encephalopathy", "Thiamine causes seizures", "None"]', 1, 'Classic board rule: "Thiamine before sugar." (First Aid)'),
    (v_topic_id, '24: Wernicke encephalopathy classic triad?', '["Rigidity, fever, autonomic instability", "Confusion, Ataxia, and Ophthalmoplegia (e.g., nystagmus, 6th nerve palsy)", "Dementia, dermatitis, diarrhea", "None"]', 1, 'An acute, reversible, life-threatening neurological emergency. (MGH Pocket)'),
    (v_topic_id, '25: Korsakoff syndrome is characterized by:', '["Ataxia only", "Chronic, irreversible anterograde/retrograde amnesia and confabulation", "Psychosis", "None"]', 1, 'The chronic phase of Wernicke-Korsakoff syndrome. (Kaplan & Sadock)'),
    (v_topic_id, '26: Which brain structure is classically damaged in Wernicke-Korsakoff syndrome?', '["Amygdala", "Mammillary bodies and medial dorsal nucleus of the thalamus", "Cerebellum", "Frontal lobe"]', 1, 'Atrophy seen on MRI. (First Aid)'),
    (v_topic_id, '27: Alcohol withdrawal symptoms typically begin how long after the last drink?', '["24-48 hours", "6-24 hours", "72 hours", "1 week"]', 1, 'Tremor, tachycardia, hypertension, sweating, anxiety. (MGH Pocket)'),
    (v_topic_id, '28: What is the most common early sign of alcohol withdrawal?', '["Seizures", "Tremor (the ''shakes'')", "Delirium tremens", "Hallucinations"]', 1, 'Often forces the patient to take a morning "eye-opener." (Kaplan & Sadock)'),
    (v_topic_id, '29: Alcoholic hallucinosis typically occurs when?', '["Within 6-24 hours of last drink", "12-48 hours; usually visual or auditory hallucinations with a CLEAR SENSORIUM", "Only after 72 hours", "None"]', 1, 'The patient knows the hallucinations aren''t real (unlike delirium). (First Aid)'),
    (v_topic_id, '30: Alcohol withdrawal seizures are typically:', '["Focal", "Generalized tonic-clonic, occurring 12-48 hours after last drink", "Absence", "None"]', 1, 'Can progress to status epilepticus if untreated. (MGH Pocket)'),
    (v_topic_id, '31: Delirium Tremens (DTs) is the most severe form of alcohol withdrawal. When does it usually peak?', '["12 hours", "48-96 hours (2-4 days) after the last drink", "1 week", "1 month"]', 1, 'Characterized by delirium, severe autonomic instability (fever, tachycardia), and hallucinations. (Kaplan & Sadock)'),
    (v_topic_id, '32: Is Delirium Tremens fatal?', '["No", "Yes, mortality is 5-20% if untreated (due to arrhythmias, cardiovascular collapse, or infection)", "Only in children", "None"]', 1, 'A medical emergency requiring ICU admission. (First Aid)'),
    (v_topic_id, '33: What is the gold standard pharmacological treatment for alcohol withdrawal?', '["Haloperidol", "Benzodiazepines (e.g., Diazepam, Lorazepam, Chlordiazepoxide)", "Beta blockers", "SSRIs"]', 1, 'Cross-tolerant with alcohol at the GABA receptor; tapers the patient down safely. (MGH Pocket)'),
    (v_topic_id, '34: Which scale is used to score the severity of alcohol withdrawal and dose benzodiazepines accordingly (symptom-triggered therapy)?', '["CAGE", "CIWA-Ar (Clinical Institute Withdrawal Assessment)", "COWS", "AIMS"]', 1, 'Assesses tremor, sweating, nausea, anxiety, agitation, etc. (Kaplan & Sadock)'),
    (v_topic_id, '35: In a patient with severe liver disease (cirrhosis) undergoing alcohol withdrawal, which benzodiazepines are preferred?', '["Diazepam and Chlordiazepoxide", "Lorazepam, Oxazepam, Temazepam (LOT)", "Alprazolam", "None"]', 1, 'LOT benzos do not require hepatic oxidation. (First Aid)'),
    (v_topic_id, '36: Can antipsychotics (e.g., Haloperidol) be used as monotherapy for alcohol withdrawal DTs?', '["Yes", "No, they lower the seizure threshold and do not treat the underlying GABA/glutamate imbalance", "Yes, first line", "None"]', 1, 'Only used as adjuncts for severe agitation AFTER adequate benzo loading. (MGH Pocket)'),
    (v_topic_id, '37: What is the mechanism of Naltrexone in treating Alcohol Use Disorder?', '["Causes vomiting if alcohol is consumed", "Mu-opioid receptor antagonist; reduces the rewarding effects (euphoria) and craving for alcohol", "Replaces alcohol", "None"]', 1, 'A first-line medication for relapse prevention. (Kaplan & Sadock)'),
    (v_topic_id, '38: In which patients is Naltrexone CONTRAINDICATED?', '["Patients with diabetes", "Patients currently taking opioids or those in acute opioid withdrawal; also severe liver failure", "Patients with hypertension", "None"]', 1, 'Will precipitate severe opioid withdrawal. (First Aid)'),
    (v_topic_id, '39: What is the mechanism of Acamprosate in treating Alcohol Use Disorder?', '["Causes vomiting", "Modulates glutamate transmission (NMDA antagonist/GABA agonist properties) to maintain abstinence", "Blocks dopamine", "None"]', 1, 'Reduces the protracted withdrawal/dysphoria that leads to relapse. (MGH Pocket)'),
    (v_topic_id, '40: In which patients is Acamprosate CONTRAINDICATED?', '["Patients with liver failure", "Patients with severe renal impairment (CrCl < 30)", "Patients on opioids", "None"]', 1, 'Cleared almost entirely by the kidneys. (Kaplan & Sadock)'),
    (v_topic_id, '41: What is the mechanism of Disulfiram (Antabuse)?', '["Reduces cravings", "Inhibits aldehyde dehydrogenase, causing a buildup of acetaldehyde if alcohol is consumed, leading to severe illness", "Blocks opioid receptors", "None"]', 1, 'Aversive conditioning. (First Aid)'),
    (v_topic_id, '42: What are the symptoms of a Disulfiram-alcohol reaction?', '["Euphoria", "Flushing, nausea, vomiting, tachycardia, hypotension, palpitations", "Seizures", "None"]', 1, 'Can be fatal (cardiovascular collapse). (MGH Pocket)'),
    (v_topic_id, '43: Is Disulfiram considered first-line for Alcohol Use Disorder?', '["Yes", "No, it is second-line due to poor compliance and safety risks; requires highly motivated patients", "Yes, for everyone", "None"]', 1, 'Often used under direct observation therapy (e.g., spouse watches them take it). (Kaplan & Sadock)'),
    (v_topic_id, '44: Topiramate is an anticonvulsant sometimes used off-label for Alcohol Use Disorder. What is its mechanism?', '["GABA agonist and Glutamate antagonist; reduces cravings", "Opioid antagonist", "None", "None"]', 0, 'Effective, but limited by cognitive side effects ("Dopamax"). (First Aid)'),
    (v_topic_id, '45: Gabapentin is sometimes used off-label for what in Alcohol Use Disorder?', '["Causing vomiting", "Treating mild withdrawal symptoms in the outpatient setting and maintaining abstinence", "Curing liver disease", "None"]', 1, 'Safe in liver disease. (MGH Pocket)'),
    (v_topic_id, '46: Fetal Alcohol Syndrome (FAS) is the leading preventable cause of:', '["Asthma", "Intellectual disability (mental retardation) in the US", "Deafness", "None"]', 1, 'Alcohol is a severe teratogen. (Kaplan & Sadock)'),
    (v_topic_id, '47: Facial features of Fetal Alcohol Syndrome include:', '["Cleft lip", "Microcephaly, short palpebral fissures, smooth philtrum, thin upper lip", "Large ears", "None"]', 1, 'Classic dysmorphic features. (First Aid)'),
    (v_topic_id, '48: Alcohol-induced Major Depressive Disorder usually resolves within:', '["Never", "2-4 weeks of abstinence", "1 year", "6 months"]', 1, 'Alcohol is a powerful depressant; always reassess mood after 4 weeks of sobriety before prescribing SSRIs. (MGH Pocket)'),
    (v_topic_id, '49: Can alcohol use disorder cause psychosis?', '["No", "Yes, alcohol-induced psychotic disorder (e.g., paranoia, alcoholic paranoia)", "Only in women", "None"]', 1, 'Often resolves with abstinence. (Kaplan & Sadock)'),
    (v_topic_id, '50: A 45yo man smells of alcohol, has a staggering gait, and is slurring his words. He denies drinking. Blood alcohol is 0.00%. Diagnosis?', '["Lying", "Stroke", "Intoxication with another CNS depressant (e.g., Benzodiazepines, Barbiturates) or a medical cause (e.g., cerebellar stroke)", "None"]', 2, 'Always keep a broad differential for ataxia. (First Aid)'),
    (v_topic_id, '51: What is the most effective psychosocial intervention for Alcohol Use Disorder?', '["Psychoanalysis", "Alcoholics Anonymous (AA) / 12-step facilitation, CBT, and Motivational Interviewing", "None", "None"]', 1, 'Peer support is incredibly powerful. (MGH Pocket)'),
    (v_topic_id, '52: What is the core philosophy of Alcoholics Anonymous (AA)?', '["Willpower", "Addiction is a chronic disease requiring complete abstinence, admitting powerlessness, and seeking help from a higher power", "Moderation", "None"]', 1, 'Total abstinence model. (Kaplan & Sadock)'),
    (v_topic_id, '53: Motivational Interviewing (MI) is based on the idea that:', '["The doctor must argue with the patient", "Patients are ambivalent about change; the therapist helps them resolve this ambivalence by eliciting their own reasons to change", "Punishment works", "None"]', 1, 'OARS: Open questions, Affirmations, Reflections, Summaries. (First Aid)'),
    (v_topic_id, '54: In the Stages of Change (Transtheoretical Model), what is "Precontemplation"?', '["Patient is making changes", "Patient does not recognize they have a problem and has no intention of changing", "Patient is planning to change", "None"]', 1, '"I don''t have a drinking problem." (MGH Pocket)'),
    (v_topic_id, '55: In the Stages of Change, what is "Contemplation"?', '["Patient is making changes", "Patient acknowledges the problem but is ambivalent about changing (weighing pros and cons)", "Patient is abstinent", "None"]', 1, '"I know drinking is hurting my liver, but it helps me sleep." (Kaplan & Sadock)'),
    (v_topic_id, '56: In the Stages of Change, what is "Preparation"?', '["Patient is ambivalent", "Patient decides to change and is making plans to do so within the next month", "Patient is abstinent", "None"]', 1, '"I''m going to call a rehab center tomorrow." (First Aid)'),
    (v_topic_id, '57: In the Stages of Change, what is "Action"?', '["Patient is ambivalent", "Patient is actively modifying their behavior (e.g., has stopped drinking and is attending AA)", "Patient is relapsing", "None"]', 1, 'Requires the most time and energy. (MGH Pocket)'),
    (v_topic_id, '58: In the Stages of Change, what is "Maintenance"?', '["Patient is ambivalent", "Patient has sustained the new behavior for at least 6 months and is working to prevent relapse", "Patient is relapsing", "None"]', 1, 'Ongoing process. (Kaplan & Sadock)'),
    (v_topic_id, '59: What is the appropriate physician response to a patient in "Precontemplation"?', '["Argue with them", "Express empathy, raise awareness of the risks, and plant seeds of doubt without confrontation", "Prescribe Disulfiram", "None"]', 1, 'Confrontation causes resistance. (First Aid)'),
    (v_topic_id, '60: Which statement defines "Binge Drinking" for men according to NIAAA?', '["1 drink a day", "5 or more drinks in about 2 hours (bringing BAC to 0.08%)", "10 drinks in a day", "None"]', 1, 'For women, it is 4 or more drinks in about 2 hours. (MGH Pocket)'),
    (v_topic_id, '61: Alcohol blackout?', '["Passing out", "Anterograde amnesia during a period of heavy drinking; the person is awake/functioning but forms no memories", "Retrograde amnesia", "None"]', 1, 'Due to hippocampus blockade by alcohol. (Kaplan & Sadock)'),
    (v_topic_id, '62: "Brownout"?', '["Passing out", "Fragmentary memory loss during intoxication, where memories can sometimes be retrieved with cues", "None", "None"]', 1, 'Less severe than a blackout. (First Aid)'),
    (v_topic_id, '63: Alcohol flush reaction (common in East Asian populations) is due to a deficiency in which enzyme?', '["Alcohol dehydrogenase", "Aldehyde dehydrogenase (ALDH2), leading to toxic acetaldehyde buildup", "Cytochrome P450", "None"]', 1, 'Causes flushing, nausea, tachycardia; biologically protects against alcoholism. (MGH Pocket)'),
    (v_topic_id, '64: What is the risk of suicide in Alcohol Use Disorder?', '["Normal", "Significantly elevated (alcohol causes depression, impulsivity, and social isolation)", "Zero", "None"]', 1, 'Major risk factor for completed suicide. (Kaplan & Sadock)'),
    (v_topic_id, '65: Dual Diagnosis refers to:', '["Having two personalities", "The co-occurrence of a Substance Use Disorder and another major Psychiatric Disorder (e.g., MDD, Schizophrenia)", "None", "None"]', 1, 'Treatment must address both simultaneously. (First Aid)'),
    (v_topic_id, '66: Formication (feeling of bugs crawling on skin) during alcohol withdrawal indicates:', '["Normal", "Alcoholic hallucinosis or impending DTs", "Schizophrenia", "None"]', 1, 'Tactile hallucinations are common in severe withdrawal. (MGH Pocket)'),
    (v_topic_id, '67: Can you give IV fluids with D5W (Dextrose) immediately to a malnourished alcoholic in the ER?', '["Yes", "No! Administer Thiamine first to prevent Wernicke''s Encephalopathy", "Only if they are young", "None"]', 1, 'Critical error to avoid. (Kaplan & Sadock)'),
    (v_topic_id, '68: What happens if you rapidly correct severe hyponatremia in a chronic alcoholic (or any patient)?', '["They get better", "Osmotic Demyelination Syndrome (Central Pontine Myelinolysis) -> locked-in syndrome", "Seizures", "None"]', 1, '"From low to high, your pons will die." (First Aid)'),
    (v_topic_id, '69: Alcoholic cerebellar degeneration primarily affects which part of the cerebellum?', '["Lateral hemispheres", "Vermis (causing truncal ataxia and wide-based gait)", "Flocculonodular lobe", "None"]', 1, 'Often irreversible. (MGH Pocket)'),
    (v_topic_id, '70: Marchiafava-Bignami disease?', '["Liver failure", "Rare demyelination of the corpus callosum seen in chronic alcoholics (classically red wine drinkers), causing dementia/coma", "Kidney failure", "None"]', 1, 'High mortality. (Kaplan & Sadock)'),
    (v_topic_id, '71: Does chronic alcohol use induce or inhibit liver CYP450 enzymes?', '["Inhibits", "Induces (increases metabolism of other drugs)", "No effect", "None"]', 1, 'e.g., requires higher doses of anesthetics. (First Aid)'),
    (v_topic_id, '72: Does ACUTE alcohol intoxication induce or inhibit liver CYP450 enzymes?', '["Induces", "Inhibits (decreases metabolism of other drugs, increasing their toxicity)", "No effect", "None"]', 1, 'Competition for the enzyme. (MGH Pocket)'),
    (v_topic_id, '73: A patient drinks alcohol while taking Metronidazole. What happens?', '["Nothing", "Disulfiram-like reaction (severe nausea, flushing, hypotension)", "Euphoria", "None"]', 1, 'Metronidazole inhibits aldehyde dehydrogenase. (Kaplan & Sadock)'),
    (v_topic_id, '74: Alcohol and Acetaminophen (Tylenol) interaction?', '["Safe", "Chronic alcohol use depletes glutathione and induces CYP2E1, drastically increasing the risk of fatal hepatotoxicity from acetaminophen", "None", "None"]', 1, 'Avoid Tylenol in alcoholics. (First Aid)'),
    (v_topic_id, '75: Best psychological approach for a patient who relapses?', '["Shame them", "Reframe relapse as a common part of the recovery process and a learning opportunity, rather than a failure", "Kick them out", "None"]', 1, 'Relapse is the rule, not the exception, in SUD. (MGH Pocket)'),
    (v_topic_id, '76: AUDIT (Alcohol Use Disorders Identification Test)?', '["Blood test", "A 10-item screening questionnaire developed by the WHO; highly accurate for identifying hazardous drinking", "Imaging", "None"]', 1, 'More comprehensive than CAGE. (Kaplan & Sadock)'),
    (v_topic_id, '77: CRAFFT questionnaire is used for?', '["Elderly", "Screening adolescents for substance use (Car, Relax, Alone, Forget, Friends, Trouble)", "Pregnant women", "None"]', 1, 'Validated tool for teens. (First Aid)'),
    (v_topic_id, '78: Is it safe to detox a patient with a history of DTs or withdrawal seizures in an outpatient setting?', '["Yes", "No, they require inpatient medical detoxification (often ICU level)", "Only with Disulfiram", "None"]', 1, 'High risk of death. (MGH Pocket)'),
    (v_topic_id, '79: Kindling phenomenon in alcohol withdrawal?', '["Starting a fire", "Repeated episodes of alcohol withdrawal become progressively more severe and more likely to involve seizures", "None", "None"]', 1, 'Due to neuroadaptation/sensitization. (Kaplan & Sadock)'),
    (v_topic_id, '80: What cardiac condition is associated with binge drinking?', '["Endocarditis", "Holiday Heart Syndrome (Atrial fibrillation or other arrhythmias occurring after a binge)", "Heart block", "None"]', 1, 'Often presents on Monday mornings. (First Aid)'),
    (v_topic_id, '81: Chronic alcohol use effect on blood pressure?', '["Lowers it", "Causes hypertension (a major reversible cause of HTN)", "No effect", "None"]', 1, 'Cessation often cures the HTN. (MGH Pocket)'),
    (v_topic_id, '82: Alcohol-related dementia vs Korsakoff?', '["Same", "Alcohol dementia is global cognitive decline (cortical atrophy); Korsakoff is specifically a severe amnesic disorder", "None", "None"]', 1, 'Both caused by chronic heavy use. (Kaplan & Sadock)'),
    (v_topic_id, '83: Does Alcohol Use Disorder run in families?', '["No", "Yes, genetics account for ~50% of the risk", "Only in women", "None"]', 1, 'Sons of alcoholic fathers are at particularly high risk. (First Aid)'),
    (v_topic_id, '84: Type I vs Type II Alcoholism (Cloninger''s typologies)?', '["Type I: Late onset, environmentally influenced, equal in men/women. Type II: Early onset, strongly genetic, mostly men, high antisocial traits.", "None", "None", "None"]', 0, 'Classic theoretical division. (MGH Pocket)'),
    (v_topic_id, '85: Is supervised injection of alcohol a treatment?', '["Yes", "No, alcohol is ingested orally", "None", "None"]', 1, 'Nonsense distractor. (Kaplan & Sadock)'),
    (v_topic_id, '86: Can a patient be diagnosed with Alcohol Use Disorder if they only drink on weekends?', '["No", "Yes, if their weekend bingeing causes clinically significant impairment (e.g., missed work on Monday, DUIs, fights)", "None", "None"]', 1, 'Pattern matters less than consequences. (First Aid)'),
    (v_topic_id, '87: Biomarker GGT (Gamma-glutamyl transferase)?', '["Specific for brain damage", "Elevated in chronic alcohol use, but less specific than PEth or CDT (elevated in many liver diseases)", "None", "None"]', 1, 'Commonly checked. (MGH Pocket)'),
    (v_topic_id, '88: Alcohol Intoxication legal threshold (0.08%) translates to roughly how many drinks in 1 hour for an average person?', '["1", "3-4 standard drinks", "10", "None"]', 1, 'Rule of thumb. (Kaplan & Sadock)'),
    (v_topic_id, '89: Delirium Tremens vs Uncomplicated Withdrawal Hallucinations?', '["DTs involves severe disorientation, altered sensorium, and autonomic instability. Uncomplicated hallucinations have a CLEAR sensorium.", "They are the same", "None", "None"]', 0, 'Crucial for prognosis. (First Aid)'),
    (v_topic_id, '90: Which neurotransmitter is acutely released during alcohol consumption causing pleasure/euphoria?', '["Acetylcholine", "Dopamine (in the nucleus accumbens) and Endorphins", "Histamine", "None"]', 1, 'The reward pathway. (MGH Pocket)'),
    (v_topic_id, '91: Why does chronic alcohol use cause tolerance?', '["Receptors die", "Brain downregulates GABA receptors and upregulates NMDA receptors to maintain homeostasis", "None", "None"]', 1, 'Explains withdrawal: when alcohol is removed, the brain is left with too much excitation (NMDA) and too little inhibition (GABA). (Kaplan & Sadock)'),
    (v_topic_id, '92: Medical consequence of chronic alcohol: Esophageal varices?', '["Caused by portal hypertension from cirrhosis; bleeding can be rapidly fatal", "Caused by coughing", "None", "None"]', 0, 'A leading cause of death in end-stage alcoholics. (First Aid)'),
    (v_topic_id, '93: What is "Craving"?', '["A choice", "An intense, urgent, or abnormal desire or longing for the substance; strongly linked to environmental cues", "None", "None"]', 1, 'Treated with Naltrexone or Acamprosate. (MGH Pocket)'),
    (v_topic_id, '94: Which medication makes drinking alcohol severely unpleasant?', '["Naltrexone", "Disulfiram", "Acamprosate", "None"]', 1, 'Punishment mechanism. (Kaplan & Sadock)'),
    (v_topic_id, '95: Which medication reduces the rewarding effects of alcohol?', '["Disulfiram", "Naltrexone", "Thiamine", "None"]', 1, 'Reward-blocking mechanism. (First Aid)'),
    (v_topic_id, '96: Which medication normalizes the brain''s chemical balance (glutamate/GABA) during abstinence?', '["Disulfiram", "Acamprosate", "Naltrexone", "None"]', 1, 'Anti-craving mechanism. (MGH Pocket)'),
    (v_topic_id, '97: Fomepizole is used for?', '["Alcohol intoxication", "Methanol or Ethylene Glycol poisoning (inhibits alcohol dehydrogenase to prevent toxic metabolite formation)", "Heroin OD", "None"]', 1, 'Toxic alcohol antidote. (Kaplan & Sadock)'),
    (v_topic_id, '98: Blindness is a classic complication of ingesting which toxic alcohol?', '["Ethanol", "Methanol (wood alcohol)", "Isopropanol", "None"]', 1, '"Snowfield vision" leading to permanent blindness. (First Aid)'),
    (v_topic_id, '99: Acute kidney failure and calcium oxalate crystals in the urine are classic for ingesting which toxic alcohol?', '["Ethanol", "Ethylene Glycol (antifreeze)", "Methanol", "None"]', 1, 'Often drunk by alcoholics when desperate or animals (tastes sweet). (MGH Pocket)'),
    (v_topic_id, '100: Summary: First line for acute severe alcohol withdrawal?', '["Haloperidol", "Benzodiazepines (e.g., Diazepam, Lorazepam)", "Naltrexone", "None"]', 1, 'Prevents seizures and DTs. (First Aid)'),

    -- SECTION 2: Opioids & Sedatives (101-180)
    (v_topic_id, '101: Opioid intoxication classic triad?', '["Dilated pupils, tachycardia, sweating", "Pinpoint pupils (miosis), Respiratory depression, and Altered mental status (coma)", "Fever, rigidity, tremor", "None"]', 1, 'Medical emergency. (First Aid)'),
    (v_topic_id, '102: Which opioid does NOT consistently cause pinpoint pupils (and may even cause dilation)?', '["Heroin", "Meperidine (Demerol)", "Fentanyl", "Morphine"]', 1, 'Meperidine has anticholinergic properties ("Demerol dilates"). (MGH Pocket)'),
    (v_topic_id, '103: What is the primary cause of death in opioid overdose?', '["Heart attack", "Respiratory depression (apnea)", "Seizures", "Liver failure"]', 1, 'Opioids decrease brainstem sensitivity to CO2. (Kaplan & Sadock)'),
    (v_topic_id, '104: Immediate life-saving treatment for opioid overdose?', '["Flumazenil", "Naloxone (Narcan) IV/IM/Intranasal and airway support", "Methadone", "Haloperidol"]', 1, 'A short-acting competitive mu-opioid receptor antagonist. (First Aid)'),
    (v_topic_id, '105: What is a major risk after giving Naloxone for a Heroin overdose?', '["It lasts forever", "Naloxone''s half-life (1 hour) is shorter than many opioids; the patient can slip back into a coma when it wears off", "None", "None"]', 1, 'Must observe the patient for several hours. (MGH Pocket)'),
    (v_topic_id, '106: Giving Naloxone to a chronic opioid user will precipitate:', '["Euphoria", "Severe, acute opioid withdrawal", "Seizures", "None"]', 1, 'Unpleasant but not life-threatening. (Kaplan & Sadock)'),
    (v_topic_id, '107: Is opioid withdrawal typically life-threatening?', '["Yes, high mortality", "No, it is extremely uncomfortable (like the worst flu of their life) but rarely fatal", "Only in men", "None"]', 1, 'Unlike alcohol/benzo withdrawal, opioid withdrawal does not cause fatal seizures. (First Aid)'),
    (v_topic_id, '108: Symptoms of opioid withdrawal include:', '["Pinpoint pupils, constipation, sleepiness", "Dilated pupils (mydriasis), diarrhea, rhinorrhea, yawning, piloerection (goosebumps), bone/muscle aches, severe anxiety", "None", "None"]', 1, 'Sympathetic rebound. (MGH Pocket)'),
    (v_topic_id, '109: What does "cold turkey" refer to in opioid withdrawal?', '["Eating turkey", "Piloerection (goosebumps) resembling plucked turkey skin", "Freezing weather", "None"]', 1, 'A classic physical sign. (Kaplan & Sadock)'),
    (v_topic_id, '110: What scale is used to assess the severity of opioid withdrawal?', '["CIWA", "COWS (Clinical Opiate Withdrawal Scale)", "PHQ-9", "None"]', 1, 'Guides treatment dosing. (First Aid)'),
    (v_topic_id, '111: Symptomatic treatment for autonomic symptoms (tachycardia, anxiety) of opioid withdrawal?', '["Haloperidol", "Clonidine (Alpha-2 agonist) or Lofexidine", "Stimulants", "None"]', 1, 'Reduces sympathetic outflow. (MGH Pocket)'),
    (v_topic_id, '112: Symptomatic treatment for diarrhea/cramps in opioid withdrawal?', '["Laxatives", "Loperamide and Dicyclomine", "None", "None"]', 1, 'Standard supportive care. (Kaplan & Sadock)'),
    (v_topic_id, '113: Long-term Medication-Assisted Treatment (MAT) for Opioid Use Disorder (OUD) includes which three FDA-approved medications?', '["Haloperidol, Lithium, Prozac", "Methadone, Buprenorphine, and Naltrexone", "None", "None"]', 1, 'MAT is the gold standard; counseling alone has massive relapse rates. (First Aid)'),
    (v_topic_id, '114: Mechanism of Methadone?', '["Antagonist", "Long-acting Mu-opioid receptor FULL AGONIST", "Partial agonist", "None"]', 1, 'Reduces cravings and prevents withdrawal without causing a severe "high" (due to slow onset). (MGH Pocket)'),
    (v_topic_id, '115: How is Methadone administered for OUD?', '["At the pharmacy", "Must be dispensed daily at a heavily regulated federal Methadone clinic (Opioid Treatment Program)", "Over the counter", "None"]', 1, 'Strict legal regulations. (Kaplan & Sadock)'),
    (v_topic_id, '116: What is a major cardiac side effect of Methadone that requires monitoring?', '["Tachycardia", "QTc prolongation (can lead to Torsades de Pointes)", "Heart block", "None"]', 1, 'Requires baseline and periodic ECGs. (First Aid)'),
    (v_topic_id, '117: Mechanism of Buprenorphine?', '["Full agonist", "Long-acting Mu-opioid receptor PARTIAL AGONIST", "Antagonist", "None"]', 1, 'High affinity but low intrinsic activity. Ceiling effect on respiratory depression. (MGH Pocket)'),
    (v_topic_id, '118: Why is Buprenorphine safer than Methadone in overdose?', '["It is a placebo", "Due to its partial agonist properties, it has a ''ceiling effect'' on respiratory depression", "None", "None"]', 1, 'Extremely hard to fatally overdose on Buprenorphine alone. (Kaplan & Sadock)'),
    (v_topic_id, '119: Buprenorphine has very HIGH affinity for the mu receptor. What happens if you give it to a patient who just used Heroin 1 hour ago?', '["Nothing", "Precipitated Withdrawal (it rips the heroin off the receptors but only partially activates them)", "Overdose", "None"]', 1, 'Must wait until the patient is in mild/moderate withdrawal (COWS > 8) before starting induction. (First Aid)'),
    (v_topic_id, '120: Why is Buprenorphine often formulated with Naloxone (Suboxone)?', '["To make it taste better", "To prevent IV diversion; if taken sublingually as prescribed, Naloxone is not absorbed. If injected, Naloxone blocks the high.", "None", "None"]', 1, 'An abuse-deterrent formulation. (MGH Pocket)'),
    (v_topic_id, '121: How is Buprenorphine prescribed?', '["Only at Methadone clinics", "By any DEA-registered provider in an office-based setting (the ''''X-waiver'''' was recently eliminated)", "Over the counter", "None"]', 1, 'Massively increases access to care compared to Methadone. (Kaplan & Sadock)'),
    (v_topic_id, '122: Mechanism of Naltrexone in OUD?', '["Full agonist", "Long-acting competitive Mu-opioid receptor ANTAGONIST", "Partial agonist", "None"]', 1, 'Blocks the effects of illicit opioids if the patient relapses. (First Aid)'),
    (v_topic_id, '123: What must a patient do before starting Naltrexone for OUD?', '["Drink alcohol", "Be completely detoxed and opioid-free for 7-14 days", "Take heroin", "None"]', 1, 'Otherwise it will precipitate severe withdrawal. (MGH Pocket)'),
    (v_topic_id, '124: Naltrexone is available in oral pills (Revia) and a long-acting injectable (Vivitrol). Which has better efficacy for OUD?', '["Pills", "Monthly injectable (Vivitrol) due to drastically better compliance", "Neither", "None"]', 1, 'Patients often skip the pill so they can get high. (Kaplan & Sadock)'),
    (v_topic_id, '125: Fentanyl is how much more potent than Morphine?', '["Same", "50 to 100 times more potent", "Less potent", "None"]', 1, 'The primary driver of the modern opioid overdose epidemic. (First Aid)'),
    (v_topic_id, '126: Carfentanil is an elephant tranquilizer sometimes mixed into street drugs. It is how much more potent than Morphine?', '["10x", "10,000 times more potent", "100x", "None"]', 1, 'Microgram quantities are lethal. (MGH Pocket)'),
    (v_topic_id, '127: Heroin (diacetylmorphine) crosses the blood-brain barrier faster than morphine. Why?', '["It is a gas", "It is highly lipophilic due to its acetyl groups, causing an intense ''rush''", "None", "None"]', 1, 'Once in the brain, it is rapidly metabolized to morphine. (Kaplan & Sadock)'),
    (v_topic_id, '128: What is "track marks"?', '["A running injury", "Scarring and hyperpigmentation along superficial veins (often arms) from repeated IV drug injection", "None", "None"]', 1, 'Physical sign of IV drug use. (First Aid)'),
    (v_topic_id, '129: Common severe infectious complications of IV drug use?', '["Pneumonia", "HIV, Hepatitis B/C, Right-sided endocarditis (Tricuspid valve), Skin abscesses, Osteomyelitis", "None", "None"]', 1, 'Requires harm reduction (e.g., needle exchanges). (MGH Pocket)'),
    (v_topic_id, '130: Which bacteria typically causes endocarditis in IV drug users?', '["E. coli", "Staphylococcus aureus", "Strep pneumo", "None"]', 1, 'Often MRSA. (Kaplan & Sadock)'),
    (v_topic_id, '131: A pregnant woman has severe Opioid Use Disorder. Best treatment approach?', '["Cold turkey detox", "Maintain on Methadone or Buprenorphine to prevent withdrawal, which can cause fetal distress/miscarriage", "Naltrexone", "None"]', 1, 'Detox is not recommended during pregnancy. (First Aid)'),
    (v_topic_id, '132: What happens to the baby born to a mother on Methadone/Buprenorphine or Heroin?', '["Nothing", "Neonatal Abstinence Syndrome (NAS); baby experiences opioid withdrawal (irritability, tremors, high-pitched cry, diarrhea)", "Schizophrenia", "None"]', 1, 'Treated with swaddling and sometimes low-dose morphine/methadone tapers. (MGH Pocket)'),
    (v_topic_id, '133: Loperamide (Imodium) is an over-the-counter anti-diarrheal. Can it be abused?', '["No", "Yes, in massive doses it crosses the BBB and causes a high, but carries a huge risk of fatal cardiac arrhythmias", "None", "None"]', 1, '"Poor man''s methadone." (Kaplan & Sadock)'),
    (v_topic_id, '134: Kratom is a plant used for pain/anxiety. How does it work?', '["It is an SSRI", "Contains mitragynine, an atypical opioid receptor agonist; can cause dependence and withdrawal", "None", "None"]', 1, 'Not FDA approved; widely available. (First Aid)'),
    (v_topic_id, '135: Sedative-Hypnotic Intoxication (Benzodiazepines, Barbiturates) presents identically to:', '["Opioid intoxication", "Alcohol intoxication (slurred speech, ataxia, incoordination, stupor)", "Stimulant intoxication", "None"]', 1, 'Both act on GABA receptors. (MGH Pocket)'),
    (v_topic_id, '136: How do you differentiate Opioid overdose from Benzodiazepine overdose clinically?', '["Benzos cause pupil dilation", "Opioids cause severe respiratory depression and pinpoint pupils; Benzos rarely cause fatal respiratory depression alone unless mixed with alcohol/opioids", "None", "None"]', 1, 'Benzos alone have a high therapeutic index. (Kaplan & Sadock)'),
    (v_topic_id, '137: The risk of fatal overdose is massively amplified when Benzodiazepines are combined with:', '["SSRIs", "Alcohol or Opioids (synergistic respiratory depression)", "Caffeine", "None"]', 1, 'A classic cause of accidental celebrity deaths. (First Aid)'),
    (v_topic_id, '138: Sedative-Hypnotic Withdrawal (Benzos/Barbiturates) presents identically to:', '["Opioid withdrawal", "Alcohol withdrawal (autonomic hyperactivity, tremors, insomnia, anxiety, SEIZURES, delirium)", "None", "None"]', 1, 'Can be fatal. (MGH Pocket)'),
    (v_topic_id, '139: Treatment for severe Benzodiazepine withdrawal?', '["Flumazenil", "Reinstitute a long-acting benzo (e.g., Diazepam) and slowly taper over weeks/months", "Haloperidol", "None"]', 1, 'Never stop abruptly. (Kaplan & Sadock)'),
    (v_topic_id, '140: Flumazenil is a GABA-A antagonist. Why is it contraindicated in a patient with chronic benzo dependence or a mixed overdose (e.g., benzo + TCA)?', '["It doesn''t work", "It will precipitate acute withdrawal and intractable seizures", "It causes liver failure", "None"]', 1, 'Almost never used in the ER. (First Aid)'),
    (v_topic_id, '141: Barbiturates (e.g., Phenobarbital) are more dangerous than Benzodiazepines because:', '["They cause cancer", "They increase the DURATION of GABA channel opening and can directly activate the channel at high doses, leading to severe respiratory depression and death", "None", "None"]', 1, 'Very low therapeutic index. (MGH Pocket)'),
    (v_topic_id, '142: Treatment for Barbiturate overdose?', '["Flumazenil", "Supportive care; alkalinize the urine (sodium bicarbonate) to enhance excretion for phenobarbital", "Naloxone", "None"]', 1, 'No direct antidote. (Kaplan & Sadock)'),
    (v_topic_id, '143: Gamma-Hydroxybutyrate (GHB) is known as a:', '["Stimulant", "''Date rape drug'' or club drug; a severe CNS depressant causing rapid coma, anterograde amnesia, and respiratory depression", "None", "None"]', 1, 'Often mixed with alcohol. (First Aid)'),
    (v_topic_id, '144: Flunitrazepam (Rohypnol) is also known as a:', '["Stimulant", "''Date rape drug'' (a highly potent, fast-acting benzodiazepine causing severe amnesia)", "None", "None"]', 1, '"Roofies." (MGH Pocket)'),
    (v_topic_id, '145: "Z-drugs" (Zolpidem, Zaleplon, Eszopiclone) are used for insomnia. Can they cause dependence?', '["No", "Yes, they act at the GABA-A receptor and can cause tolerance, dependence, and withdrawal similar to benzos", "None", "None"]', 1, 'Also cause complex sleep behaviors (sleep-eating, sleep-driving). (Kaplan & Sadock)'),
    (v_topic_id, '146: What is the most effective approach to treating chronic insomnia rather than long-term Z-drugs?', '["More drugs", "CBT for Insomnia (CBT-I) and sleep hygiene", "Alcohol", "None"]', 1, 'Medications lose efficacy over time. (First Aid)'),
    (v_topic_id, '147: Opioid-induced hyperalgesia?', '["No pain", "Paradoxical increase in pain sensitivity seen with chronic, high-dose opioid therapy", "None", "None"]', 1, 'Treated by tapering the opioid. (MGH Pocket)'),
    (v_topic_id, '148: Do patients develop tolerance to the CONSTIPATION caused by opioids?', '["Yes, quickly", "No, miosis and constipation rarely develop tolerance", "Only in men", "None"]', 1, 'Must prescribe a bowel regimen (e.g., Senna) with chronic opioids. (Kaplan & Sadock)'),
    (v_topic_id, '149: Do patients develop tolerance to the MIOSIS (pinpoint pupils) caused by opioids?', '["Yes", "No", "Only if they use heroin", "None"]', 1, 'A reliable sign of use even in chronic users. (First Aid)'),
    (v_topic_id, '150: What is Pseudoaddiction?', '["Faking drug use", "Drug-seeking behavior (clock-watching, asking for early refills) that is actually caused by UNDER-TREATMENT of severe pain, which resolves when pain is adequately treated", "None", "None"]', 1, 'A critical distinction from true OUD. (MGH Pocket)'),
    (v_topic_id, '151: Does Naltrexone help with opioid cravings?', '["No", "Yes, but it requires the patient to be highly motivated since they can just stop taking it to get high", "Only for alcohol", "None"]', 1, 'MAT with agonists (Methadone/Bup) generally has better retention rates. (Kaplan & Sadock)'),
    (v_topic_id, '152: A patient on Methadone wants to switch to Buprenorphine. What is the risk?', '["None", "Severe precipitated withdrawal if the methadone is not tapered down to a low dose (e.g., <30mg) and stopped for several days before starting Buprenorphine", "None", "None"]', 1, 'Methadone has a very long half-life. (First Aid)'),
    (v_topic_id, '153: Buprenorphine can be administered as a sublingual film or as:', '["IV only", "A monthly long-acting injection (Sublocade) or a 6-month subdermal implant (Probuphine)", "None", "None"]', 1, 'Improves compliance. (MGH Pocket)'),
    (v_topic_id, '154: Which opioid is commonly abused by medical professionals due to its short half-life and lack of pupil constriction?', '["Heroin", "Meperidine (Demerol)", "Fentanyl", "Methadone"]', 1, 'Classic board scenario. (Kaplan & Sadock)'),
    (v_topic_id, '155: Meperidine carries a unique risk of causing what if combined with MAOIs?', '["Bleeding", "Serotonin Syndrome (meperidine has serotonergic activity)", "Liver failure", "None"]', 1, 'Fatal interaction. (First Aid)'),
    (v_topic_id, '156: Meperidine metabolite (Normeperidine) can accumulate in renal failure and cause:', '["Coma", "Seizures", "Blindness", "None"]', 1, 'Avoid in renal impairment. (MGH Pocket)'),
    (v_topic_id, '157: Tramadol is a weak mu-agonist and SNRI. What are its two major unique risks?', '["None", "Lowers seizure threshold and risk of Serotonin Syndrome", "Liver failure", "None"]', 1, 'Not completely benign. (Kaplan & Sadock)'),
    (v_topic_id, '158: Dextromethorphan (Robitussin) is a cough syrup. How is it abused?', '["It''s an opioid", "In high doses, it acts as an NMDA receptor antagonist (like PCP/Ketamine), causing dissociative hallucinations", "None", "None"]', 1, '"Robotripping." (First Aid)'),
    (v_topic_id, '159: Clonidine suppresses which symptoms of opioid withdrawal?', '["Cravings", "Autonomic symptoms (tachycardia, sweating, hypertension)", "Pain", "None"]', 1, 'Does not treat cravings or muscle aches. (MGH Pocket)'),
    (v_topic_id, '160: Naloxone vs Naltrexone?', '["Same drug", "Naloxone = short-acting antagonist used to REVERSE acute overdose. Naltrexone = long-acting antagonist used to PREVENT relapse.", "None", "None"]', 1, 'Must know this distinction. (Kaplan & Sadock)'),
    (v_topic_id, '161: Buprenorphine receptor profile?', '["Full agonist", "Partial mu agonist, Kappa antagonist", "None", "None"]', 1, 'Unique profile. (First Aid)'),
    (v_topic_id, '162: Methadone half-life?', '["1 hour", "Extremely long (24-150 hours) and highly variable due to lipophilicity", "None", "None"]', 1, 'High risk of accidental overdose during induction. (MGH Pocket)'),
    (v_topic_id, '163: Methadone and pregnancy?', '["Category X", "Standard of care for OUD in pregnancy to prevent withdrawal", "None", "None"]', 1, 'Buprenorphine is also standard of care now. (Kaplan & Sadock)'),
    (v_topic_id, '164: Harm reduction strategies for OUD include?', '["Arrest", "Needle exchange programs, supervised injection sites, and widespread Narcan distribution", "None", "None"]', 1, 'Evidence-based to save lives and prevent HIV/HCV. (First Aid)'),
    (v_topic_id, '165: Benzodiazepine intoxication vs alcohol intoxication?', '["Benzos don''t cause ataxia", "Clinically identical, but benzos generally have less cognitive impairment and nausea", "None", "None"]', 1, 'Both cause nystagmus and slurred speech. (MGH Pocket)'),
    (v_topic_id, '166: A 20yo takes a handful of Xanax in a suicide attempt. Vital signs are normal, patient is sleeping but arousable. Next step?', '["Intubate", "Observe and support; pure benzo overdose is rarely fatal", "Give Flumazenil", "None"]', 1, 'Protect the airway. (Kaplan & Sadock)'),
    (v_topic_id, '167: If the same 20yo took Xanax AND drank a bottle of vodka?', '["Observe", "High risk of fatal respiratory depression; monitor airway closely/intubate if needed", "None", "None"]', 1, 'Synergistic toxicity. (First Aid)'),
    (v_topic_id, '168: Propofol is a rapid-acting IV sedative. What is "Propofol Infusion Syndrome"?', '["Euphoria", "Metabolic acidosis, rhabdomyolysis, heart failure, and death from prolonged high-dose infusions", "None", "None"]', 1, 'Mostly an ICU concern. (MGH Pocket)'),
    (v_topic_id, '169: Ketamine is a dissociative anesthetic. Mechanism?', '["GABA agonist", "NMDA receptor antagonist", "Serotonin agonist", "None"]', 1, 'Preserves respiratory drive; can cause emergence delirium. (Kaplan & Sadock)'),
    (v_topic_id, '170: Opioid withdrawal duration for Heroin?', '["1 month", "Peaks in 2-3 days, resolves in 7-10 days", "None", "None"]', 1, 'Short-acting opioid. (First Aid)'),
    (v_topic_id, '171: Opioid withdrawal duration for Methadone?', '["7 days", "Onset is delayed (2-4 days), peaks around a week, can last for weeks", "None", "None"]', 1, 'Protracted withdrawal due to long half-life. (MGH Pocket)'),
    (v_topic_id, '172: Fentanyl testing strips?', '["Used by police only", "Given to users to test their drugs (e.g., cocaine, counterfeit pills) for fentanyl contamination to prevent overdose", "None", "None"]', 1, 'Harm reduction tool. (Kaplan & Sadock)'),
    (v_topic_id, '173: Xylazine ("Tranq")?', '["A harmless filler", "An animal tranquilizer (alpha-2 agonist) increasingly cut into fentanyl; causes severe necrotic skin ulcers and is NOT reversed by Naloxone", "None", "None"]', 1, 'A massive emerging public health crisis. (First Aid)'),
    (v_topic_id, '174: If a patient overdoses on Fentanyl cut with Xylazine, will Naloxone work?', '["Yes completely", "Naloxone will reverse the opioid/fentanyl part, but the patient may remain heavily sedated from the Xylazine", "None", "None"]', 1, 'Requires rescue breathing/supportive care. (MGH Pocket)'),
    (v_topic_id, '175: What is the most common cause of non-fatal opioid overdose?', '["Using at a party", "Using the usual dose after a period of abstinence (e.g., leaving rehab or prison), because tolerance has plummeted", "None", "None"]', 1, 'A critical counseling point for patients leaving detox. (Kaplan & Sadock)'),
    (v_topic_id, '176: OUD severity is often linked to the route of administration. Rank from fastest onset/highest addiction potential to lowest?', '["Oral -> Snorting -> Smoking -> IV", "IV -> Smoking -> Snorting -> Oral", "None", "None"]', 1, 'Speed of dopamine spike dictates addictiveness. (First Aid)'),
    (v_topic_id, '177: Prescription Drug Monitoring Programs (PDMPs)?', '["Police databases", "State databases that track controlled substance prescriptions to prevent ''doctor shopping''", "None", "None"]', 1, 'Must check before prescribing opioids/benzos. (MGH Pocket)'),
    (v_topic_id, '178: Miosis is caused by opioid stimulation of which cranial nerve nucleus?', '["CN II", "Edinger-Westphal nucleus of CN III (Parasympathetic)", "CN VII", "None"]', 1, 'Anatomy correlation. (Kaplan & Sadock)'),
    (v_topic_id, '179: Endogenous opioids include:', '["Dopamine", "Endorphins, Enkephalins, Dynorphins", "Serotonin", "None"]', 1, 'The body''s natural painkillers. (First Aid)'),
    (v_topic_id, '180: Summary: Best maintenance for severe OUD?', '["Naltrexone", "Buprenorphine or Methadone", "Therapy only", "None"]', 1, 'Agonist therapy saves lives. (MGH Pocket)'),

    -- SECTION 3: Stimulants, Hallucinogens, Cannabis (181-250)
    (v_topic_id, '181: Cocaine mechanism of action?', '["Releases dopamine", "Blocks the reuptake of dopamine, norepinephrine, and serotonin (SNDRI)", "GABA agonist", "None"]', 1, 'Prolongs catecholamine action in the synapse. (First Aid)'),
    (v_topic_id, '182: Amphetamine / Methamphetamine mechanism of action?', '["Blocks reuptake only", "Forces the release of dopamine/norepinephrine from presynaptic vesicles AND blocks reuptake", "None", "None"]', 1, 'More potent and longer-lasting than cocaine. (MGH Pocket)'),
    (v_topic_id, '183: Stimulant Intoxication (Cocaine/Meth) presents with:', '["Pinpoint pupils, bradycardia", "Dilated pupils (mydriasis), tachycardia, hypertension, diaphoresis, grandiosity, psychomotor agitation", "None", "None"]', 1, 'Massive sympathetic overdrive. (Kaplan & Sadock)'),
    (v_topic_id, '184: Severe complications of Cocaine intoxication?', '["Sleepiness", "Coronary vasospasm (myocardial infarction), arrhythmias, strokes, and seizures", "None", "None"]', 1, 'Cocaine can cause a heart attack in a healthy 20-year-old. (First Aid)'),
    (v_topic_id, '185: A patient with chest pain from cocaine intoxication should NOT be given which class of medication?', '["Benzodiazepines", "Beta-blockers (can cause unopposed alpha-adrenergic stimulation, worsening hypertension/vasospasm)", "Aspirin", "None"]', 1, 'Give Benzos to calm the patient and lower BP/HR instead. (MGH Pocket)'),
    (v_topic_id, '186: Chronic cocaine snorting causes what physical exam finding?', '["Rotting teeth", "Nasal mucosal atrophy and septal perforation", "Track marks", "None"]', 1, 'Due to chronic ischemia from vasoconstriction. (Kaplan & Sadock)'),
    (v_topic_id, '187: Chronic methamphetamine smoking causes what physical exam finding?', '["Septal perforation", "Severe dental decay (''Meth mouth'') and skin excoriations from picking at ''bugs''", "None", "None"]', 1, 'Due to poor hygiene, dry mouth, and bruxism. (First Aid)'),
    (v_topic_id, '188: Stimulant Withdrawal (the "crash") presents with:', '["Tachycardia, euphoria, insomnia", "Profound fatigue, vivid nightmares, hypersomnia, hyperphagia (increased appetite), and severe depression/suicidality", "None", "None"]', 1, 'The exact opposite of intoxication. (MGH Pocket)'),
    (v_topic_id, '189: Is stimulant withdrawal life-threatening?', '["Yes, high risk of seizures", "No, it is not physically life-threatening, but the risk of SUICIDE during the severe depressive crash is high", "None", "None"]', 1, 'Monitor for suicidal ideation. (Kaplan & Sadock)'),
    (v_topic_id, '190: Pharmacological treatment for Stimulant Use Disorder?', '["Methadone", "There are no FDA-approved medications; treatment is entirely psychosocial (e.g., Contingency Management, CBT)", "Buprenorphine", "None"]', 1, 'A major gap in addiction medicine. (First Aid)'),
    (v_topic_id, '191: What is Contingency Management?', '["Talking therapy", "A highly effective behavioral therapy where patients receive tangible rewards (vouchers, cash) for providing drug-free urine screens", "None", "None"]', 1, 'Operant conditioning. (MGH Pocket)'),
    (v_topic_id, '192: Synthetic Cathinones are commonly sold as:', '["Heroin", "''Bath Salts''", "Weed", "None"]', 1, 'Amphetamine-like stimulants that cause severe agitation, paranoia, and violent psychosis. (Kaplan & Sadock)'),
    (v_topic_id, '193: What happens when cocaine and alcohol are used together?', '["Nothing", "They form cocaethylene in the liver, which is more toxic, lasts longer, and has a higher risk of sudden cardiac death", "None", "None"]', 1, 'A highly lethal combination. (First Aid)'),
    (v_topic_id, '194: Cocaine-induced psychosis frequently involves which type of hallucination?', '["Visual", "Tactile (formication - feeling bugs under the skin) and severe paranoia", "None", "None"]', 1, 'Also called "cocaine bugs." (MGH Pocket)'),
    (v_topic_id, '195: Cannabis (Marijuana) active ingredient?', '["CBD", "Delta-9-tetrahydrocannabinol (THC); acts as a partial agonist at CB1 cannabinoid receptors in the brain", "None", "None"]', 1, 'CBD is non-psychoactive and may have anxiolytic properties. (Kaplan & Sadock)'),
    (v_topic_id, '196: Cannabis Intoxication presents with:', '["Aggression, pinpoint pupils", "Euphoria, increased appetite (munchies), impaired time perception, dry mouth, CONJUNCTIVAL INJECTION (red eyes), tachycardia", "None", "None"]', 1, 'Red eyes are a classic physical sign. (First Aid)'),
    (v_topic_id, '197: High doses of Cannabis (especially edibles) can cause:', '["Coma", "Severe anxiety, panic attacks, paranoia, and transient psychosis", "Respiratory depression", "None"]', 1, 'Very common ER presentation. (MGH Pocket)'),
    (v_topic_id, '198: Cannabis Withdrawal presents with:', '["Seizures", "Irritability, insomnia, vivid dreams, decreased appetite, and restlessness", "Hypersomnia", "None"]', 1, 'Peaks in 2-3 days, can last 1-2 weeks. (Kaplan & Sadock)'),
    (v_topic_id, '199: Is Cannabis addictive?', '["No", "Yes, ~9% of adult users and up to 17% of adolescent users develop Cannabis Use Disorder", "Only if injected", "None"]', 1, 'Modern high-THC strains carry higher risks. (First Aid)'),
    (v_topic_id, '200: Cannabinoid Hyperemesis Syndrome?', '["Hunger", "Cyclic severe nausea and vomiting in chronic heavy cannabis users. Classically relieved by taking HOT SHOWERS.", "None", "None"]', 1, 'Often misdiagnosed as cyclical vomiting syndrome. (MGH Pocket)'),
    (v_topic_id, '201: How long does Cannabis stay in the urine?', '["1 day", "Single use: ~3 days. Chronic heavy use: up to 1 month (due to high lipophilicity, stored in fat)", "1 year", "None"]', 1, 'Crucial for drug testing interpretation. (Kaplan & Sadock)'),
    (v_topic_id, '202: Early adolescent cannabis use is epidemiologically linked to an increased risk of developing which psychiatric disorder later in life?', '["Bipolar", "Schizophrenia (especially in genetically vulnerable individuals)", "OCD", "None"]', 1, 'A major public health concern. (First Aid)'),
    (v_topic_id, '203: Synthetic Cannabinoids (K2, Spice) differ from natural cannabis how?', '["They are weaker", "They are FULL agonists at CB1 receptors, highly potent, not detected on standard urine screens, and can cause severe seizures, psychosis, and death", "None", "None"]', 1, 'Extremely dangerous. (MGH Pocket)'),
    (v_topic_id, '204: Hallucinogens (Classic Psychedelics) include:', '["Cocaine, Meth", "LSD, Psilocybin (magic mushrooms), Mescaline (peyote), DMT", "Heroin", "None"]', 1, 'Primarily act as Serotonin 5-HT2A receptor agonists. (Kaplan & Sadock)'),
    (v_topic_id, '205: Hallucinogen Intoxication presents with:', '["Coma", "Visual hallucinations, illusions, altered sense of time, SYNesthesia (hearing colors), mydriasis, tachycardia", "None", "None"]', 1, 'Usually a clear sensorium, but altered perception. (First Aid)'),
    (v_topic_id, '206: What is a "Bad Trip"?', '["Vomiting", "Severe panic, anxiety, and terrifying hallucinations during intoxication", "None", "None"]', 1, 'Treated with reassurance (''talking down'') and Benzodiazepines if needed. (MGH Pocket)'),
    (v_topic_id, '207: Do classic hallucinogens (LSD, Psilocybin) cause physical dependence or withdrawal?', '["Yes, severe", "No, they do not cause withdrawal and have very low addiction potential", "Only in men", "None"]', 1, 'Rapid tolerance occurs, but no physical withdrawal. (Kaplan & Sadock)'),
    (v_topic_id, '208: Hallucinogen Persisting Perception Disorder (HPPD)?', '["Schizophrenia", "Re-experiencing of perceptual symptoms (flashbacks, halos, trails) long after the drug has worn off", "None", "None"]', 1, 'Can cause significant distress. (First Aid)'),
    (v_topic_id, '209: PCP (Phencyclidine) / Angel Dust mechanism?', '["Serotonin agonist", "NMDA receptor antagonist (dissociative) and dopamine reuptake inhibitor", "GABA agonist", "None"]', 1, 'Produces a unique state of dissociation and stimulation. (MGH Pocket)'),
    (v_topic_id, '210: PCP Intoxication classically presents with:', '["Relaxation", "Severe agitation, aggression, IMPULSIVITY, analgesia (feeling no pain), superhuman strength, and ROTARY NYSTAGMUS", "None", "None"]', 1, 'Rotary nystagmus is a board buzzword. (Kaplan & Sadock)'),
    (v_topic_id, '211: Treatment for PCP intoxication/agitation?', '["Talk down", "Benzodiazepines or Antipsychotics (e.g., Haloperidol). Do NOT try to ''talk down'' a PCP patient; minimize sensory stimulation.", "None", "None"]', 1, 'Patient is completely dissociated and may become violent. (First Aid)'),
    (v_topic_id, '212: MDMA (Ecstasy/Molly) is a:', '["Depressant", "Synthetic amphetamine derivative (hallucinogenic stimulant) that causes massive release of Serotonin, Dopamine, and NE", "None", "None"]', 1, 'Promotes feelings of empathy, closeness, and euphoria. (MGH Pocket)'),
    (v_topic_id, '213: Severe medical complications of MDMA intoxication?', '["Sleepiness", "Hyperthermia, dehydration, severe HYPONATREMIA (due to water intoxication and SIADH), and Serotonin Syndrome", "None", "None"]', 1, 'Rave attendees dancing in hot clubs can die of heatstroke or brain edema from hyponatremia. (Kaplan & Sadock)'),
    (v_topic_id, '214: MDMA "crash" consists of:', '["Euphoria", "Severe depression, lethargy, and jaw clenching (bruxism) for days after use due to serotonin depletion", "None", "None"]', 1, '"Suicide Tuesday" after a weekend rave. (First Aid)'),
    (v_topic_id, '215: Dronabinol is:', '["A street drug", "FDA-approved synthetic THC pill used for chemotherapy-induced nausea and AIDS anorexia", "None", "None"]', 1, 'Medical use of cannabinoids. (MGH Pocket)'),
    (v_topic_id, '216: Salvia Divinorum is a hallucinogenic plant. Mechanism?', '["Serotonin agonist", "Kappa-opioid receptor agonist; causes intense, brief (15 min) dissociative hallucinations", "None", "None"]', 1, 'Often smoked. (Kaplan & Sadock)'),
    (v_topic_id, '217: Can LSD cause a false positive for PCP on a urine drug screen?', '["Yes", "No, standard urine drug screens (UDS) do NOT detect LSD or Psilocybin", "None", "None"]', 1, 'Requires specialized testing. (First Aid)'),
    (v_topic_id, '218: Which drugs commonly cause false positives for Amphetamines on a UDS?', '["Water", "Bupropion, Pseudoephedrine, Labetalol, Trazodone", "None", "None"]', 1, 'Always verify unexpected positives with GC/MS (Gas Chromatography/Mass Spectrometry). (MGH Pocket)'),
    (v_topic_id, '219: Which drugs commonly cause false positives for PCP on a UDS?', '["Aspirin", "Dextromethorphan, Venlafaxine, Ibuprofen, Diphenhydramine", "None", "None"]', 1, 'Very common false positive. (Kaplan & Sadock)'),
    (v_topic_id, '220: Does eating poppy seed bagels cause a positive UDS for opioids?', '["No", "Yes, can cause a true positive for Morphine/Codeine (though thresholds have been raised to prevent this)", "None", "None"]', 1, 'A classic clinical scenario. (First Aid)'),
    (v_topic_id, '221: Amotivational Syndrome?', '["Depression", "Controversial syndrome in chronic heavy cannabis users characterized by apathy, lack of motivation, and poor school/work performance", "None", "None"]', 1, 'Unclear if cannabis causes it or if it reflects underlying depression. (MGH Pocket)'),
    (v_topic_id, '222: Medical Marijuana evidence is strongest for:', '["Curing cancer", "Chronic pain, neuropathic pain, and spasticity in Multiple Sclerosis", "None", "None"]', 1, 'Evidence for treating psychiatric disorders is currently weak/negative. (Kaplan & Sadock)'),
    (v_topic_id, '223: Ayahuasca active ingredient?', '["THC", "DMT (a potent hallucinogen) combined with a plant-based MAOI to prevent its breakdown in the gut", "None", "None"]', 1, 'Traditional Amazonian brew. (First Aid)'),
    (v_topic_id, '224: Khat (Cathinone) is a plant chewed in East Africa/Yemen for:', '["Sleep", "Mild stimulant effects similar to amphetamines", "None", "None"]', 1, 'The natural version of "Bath Salts." (MGH Pocket)'),
    (v_topic_id, '225: Standard UDS detects Cannabis (THC) for how long?', '["1 hour", "Up to 30 days in heavy users", "None", "None"]', 1, 'UDS detects the inactive metabolite (THC-COOH). (Kaplan & Sadock)'),
    (v_topic_id, '226: Standard UDS detects Cocaine for how long?', '["1 month", "2-4 days (detects the metabolite benzoylecgonine)", "None", "None"]', 1, 'Very short detection window. (First Aid)'),
    (v_topic_id, '227: Standard UDS detects Amphetamines for how long?', '["1 month", "1-3 days", "None", "None"]', 1, 'Short window. (MGH Pocket)'),
    (v_topic_id, '228: Standard UDS detects Opioids for how long?', '["1 month", "2-4 days", "None", "None"]', 1, 'Note: Standard UDS often tests for Morphine/Codeine/Heroin, but may MISS synthetic opioids like Fentanyl, Methadone, or Buprenorphine unless specifically ordered! (Kaplan & Sadock)'),
    (v_topic_id, '229: Cocaine + Beta Blockers?', '["Safe", "Risk of unopposed alpha stimulation leading to severe hypertension/coronary spasm", "None", "None"]', 1, 'Never give Propranolol to a cocaine overdose. (First Aid)'),
    (v_topic_id, '230: Methamphetamine neurotoxicity?', '["None", "Highly neurotoxic to dopamine and serotonin neurons; chronic use causes long-lasting cognitive deficits and Parkinsonian symptoms", "None", "None"]', 1, 'Destroys brain tissue. (MGH Pocket)'),
    (v_topic_id, '231: Cocaine use in pregnancy?', '["Safe", "Causes vasoconstriction leading to placental abruption, prematurity, and low birth weight", "None", "None"]', 1, 'Obstetric emergency risk. (Kaplan & Sadock)'),
    (v_topic_id, '232: Macaw-like speech or rapid, pressured speech?', '["Depression", "Stimulant intoxication or Mania", "None", "None"]', 1, 'Differential diagnosis is key. (First Aid)'),
    (v_topic_id, '233: Tactile hallucinations (formication)?', '["Schizophrenia", "Cocaine/Meth intoxication OR Alcohol withdrawal", "None", "None"]', 1, 'Always suspect substances first. (MGH Pocket)'),
    (v_topic_id, '234: "Crack" vs Powder Cocaine?', '["Same", "Crack is the freebase form; smoked for a much faster, more intense, and highly addictive high", "None", "None"]', 1, 'Pharmacokinetics drive addiction. (Kaplan & Sadock)'),
    (v_topic_id, '235: Form of Cannabis with highest THC concentration?', '["Joint", "Dabs / Shatter / Wax (Butane Hash Oil) - can be >80% THC", "None", "None"]', 1, 'Causes higher rates of psychosis. (First Aid)'),
    (v_topic_id, '236: Synesthesia?', '["Hearing loss", "A blending of senses (e.g., tasting colors, hearing images), classic for LSD", "None", "None"]', 1, 'Hallmark of psychedelics. (MGH Pocket)'),
    (v_topic_id, '237: PCP vs Ketamine?', '["Same drug", "Both NMDA antagonists, but Ketamine is shorter-acting and generally less likely to cause severe violent agitation", "None", "None"]', 1, 'Ketamine is used medically. (Kaplan & Sadock)'),
    (v_topic_id, '238: Psychedelics in modern psychiatry?', '["Banned", "Psilocybin and MDMA are undergoing FDA trials for TRD and PTSD", "None", "None"]', 1, 'A renaissance in psychedelic medicine. (First Aid)'),
    (v_topic_id, '239: Bruxism (teeth grinding)?', '["Heroin", "Classic sign of MDMA (Ecstasy) use; ravers often use pacifiers", "None", "None"]', 1, 'Physical exam clue. (MGH Pocket)'),
    (v_topic_id, '240: Paranoia and increased appetite?', '["Cocaine", "Cannabis", "None", "None"]', 1, 'The munchies. (Kaplan & Sadock)'),
    (v_topic_id, '241: Belligerence, nystagmus, analgesia?', '["Alcohol", "PCP", "None", "None"]', 1, 'The classic PCP triad. (First Aid)'),
    (v_topic_id, '242: Euphoria, pupillary dilation, tachycardia?', '["Heroin", "Cocaine/Amphetamine", "None", "None"]', 1, 'Stimulant triad. (MGH Pocket)'),
    (v_topic_id, '243: Anxiety, muscle aches, yawning, diarrhea?', '["Cocaine crash", "Opioid withdrawal", "None", "None"]', 1, 'Flu-like syndrome. (Kaplan & Sadock)'),
    (v_topic_id, '244: Depression, hypersomnia, hyperphagia?', '["Opioid withdrawal", "Cocaine/Stimulant withdrawal", "None", "None"]', 1, 'The crash. (First Aid)'),
    (v_topic_id, '245: Rebound REM sleep (vivid dreams)?', '["Occurs after stopping Cannabis or Alcohol (which suppress REM)", "None", "None", "None"]', 0, 'Can be distressing. (MGH Pocket)'),
    (v_topic_id, '246: Drug testing hair follicles?', '["Tests 1 day", "Can detect drug use for the past 90 days", "None", "None"]', 1, 'Longest detection window. (Kaplan & Sadock)'),
    (v_topic_id, '247: Drug testing blood?', '["Longest window", "Shortest window (detects current intoxication)", "None", "None"]', 1, 'Used in DUI cases. (First Aid)'),
    (v_topic_id, '248: Drug testing urine?', '["Useless", "Most common, detects metabolites for days to weeks", "None", "None"]', 1, 'Standard of care. (MGH Pocket)'),
    (v_topic_id, '249: False negative urine drug screen?', '["Patient drank too much water (dilute urine) or used a synthetic drug not on the panel", "None", "None", "None"]', 0, 'Check urine creatinine/specific gravity. (Kaplan & Sadock)'),
    (v_topic_id, '250: Summary: Acute PCP agitation treatment?', '["Talk therapy", "Benzodiazepines", "Restraints only", "None"]', 1, 'Chemical restraint is safest. (First Aid)'),

    -- SECTION 4: Tobacco, Inhalants, Other Addictions & Pharmacology (251-300)
    (v_topic_id, '251: What is the most preventable cause of death in the United States?', '["Alcohol", "Tobacco smoking", "Opioids", "Cocaine"]', 1, 'Causes 480,000 deaths annually in the US. (Kaplan & Sadock)'),
    (v_topic_id, '252: Nicotine mechanism of action?', '["Blocks dopamine", "Agonist at nicotinic acetylcholine receptors in the VTA, causing dopamine release in the nucleus accumbens", "None", "None"]', 1, 'Highly addictive. (First Aid)'),
    (v_topic_id, '253: Nicotine withdrawal symptoms?', '["Seizures", "Irritability, anxiety, restlessness, poor concentration, increased appetite, and intense cravings", "Coma", "None"]', 1, 'Peaks in 2-3 days, lasts weeks. (MGH Pocket)'),
    (v_topic_id, '254: First-line pharmacological treatments for Tobacco Use Disorder?', '["Nicotine Replacement Therapy (NRT), Varenicline, Bupropion", "Haloperidol", "SSRIs", "None"]', 0, 'Combining NRT (patch + gum) is highly effective. (Kaplan & Sadock)'),
    (v_topic_id, '255: Mechanism of Varenicline (Chantix)?', '["Full agonist", "Partial agonist at the alpha-4 beta-2 nicotinic acetylcholine receptor", "Antagonist", "None"]', 1, 'Reduces cravings and blocks the rewarding effects of smoking if they relapse. (First Aid)'),
    (v_topic_id, '256: Mechanism of Bupropion (Zyban) in smoking cessation?', '["Nicotine agonist", "Norepinephrine and Dopamine reuptake inhibitor (NDRI); reduces cravings and withdrawal", "None", "None"]', 1, 'Also useful if the patient has comorbid depression. (MGH Pocket)'),
    (v_topic_id, '257: Contraindications for Bupropion?', '["Hypertension", "History of seizures or Eating Disorders (Anorexia/Bulimia)", "Depression", "None"]', 1, 'Lowers the seizure threshold. (Kaplan & Sadock)'),
    (v_topic_id, '258: Varenicline black box warning (historically)?', '["Liver failure", "Neuropsychiatric side effects (suicidality, vivid dreams, depression) - though the FDA removed the black box warning in 2016 due to newer safety data", "None", "None"]', 1, 'Still monitor for mood changes. (First Aid)'),
    (v_topic_id, '259: Should a patient stop smoking immediately when starting Varenicline or Bupropion?', '["Yes", "No, they usually start the med 1-2 weeks BEFORE their target quit date to let the drug build up", "None", "None"]', 1, 'Standard prescribing protocol. (MGH Pocket)'),
    (v_topic_id, '260: Caffeine mechanism of action?', '["Dopamine agonist", "Antagonist at Adenosine receptors", "Serotonin agonist", "None"]', 1, 'Adenosine normally promotes sleep. (Kaplan & Sadock)'),
    (v_topic_id, '261: Caffeine Intoxication presents with:', '["Sleepiness", "Restlessness, insomnia, diuresis, muscle twitching, tachycardia/arrhythmia", "Bradycardia", "None"]', 1, 'Usually requires >250mg (2-3 cups of coffee). (First Aid)'),
    (v_topic_id, '262: Caffeine Withdrawal hallmark symptom?', '["Seizures", "Throbbing headache, fatigue, irritability", "Diarrhea", "None"]', 1, 'Starts 12-24 hours after last use. (MGH Pocket)'),
    (v_topic_id, '263: Does DSM-5 recognize "Caffeine Use Disorder"?', '["Yes", "No, it is a condition for further study (though Caffeine Intoxication and Withdrawal are official diagnoses)", "None", "None"]', 1, 'Nuance in DSM-5. (Kaplan & Sadock)'),
    (v_topic_id, '264: Inhalant Intoxication (glue, paint thinner, nitrous oxide) presents similarly to:', '["Cocaine", "Alcohol intoxication (euphoria, slurred speech, ataxia, dizziness)", "None", "None"]', 1, 'Very rapid onset and offset (minutes). (First Aid)'),
    (v_topic_id, '265: What is the most dangerous acute risk of Inhalant use?', '["Blindness", "''Sudden Sniffing Death'' due to fatal cardiac arrhythmias (ventricular fibrillation) caused by sensitization of the heart to catecholamines", "None", "None"]', 1, 'Can happen on the first use. (MGH Pocket)'),
    (v_topic_id, '266: Chronic Inhalant abuse causes severe damage to which organ?', '["Stomach", "Brain (widespread demyelination, cortical atrophy, dementia) and peripheral neuropathy", "None", "None"]', 1, 'Solvents dissolve the myelin sheath (lipid-rich). (Kaplan & Sadock)'),
    (v_topic_id, '267: Physical exam clue for Inhalant abuse?', '["Track marks", "Rash or irritation around the mouth and nose (''huffer''s rash'')", "Rotting teeth", "None"]', 1, 'Often seen in adolescents. (First Aid)'),
    (v_topic_id, '268: Nitrous Oxide (Whippets) abuse specifically causes depletion of which vitamin?', '["Vitamin C", "Vitamin B12, leading to megaloblastic anemia and subacute combined degeneration of the spinal cord (neuropathy/ataxia)", "Vitamin D", "None"]', 1, 'Classic board question. (MGH Pocket)'),
    (v_topic_id, '269: Anabolic-Androgenic Steroids (Testosterone derivatives) abuse causes what psychiatric symptoms?', '["Apathy", "Severe irritability, aggression (''roid rage''), mania, and sometimes depression upon withdrawal", "None", "None"]', 1, 'Often used by bodybuilders. (Kaplan & Sadock)'),
    (v_topic_id, '270: Physical signs of Anabolic Steroid abuse in men?', '["Weight loss", "Acne, gynecomastia, testicular atrophy, and premature baldness", "None", "None"]', 1, 'Due to exogenous suppression of the HPG axis and conversion to estrogen. (First Aid)'),
    (v_topic_id, '271: Does DSM-5 include any non-substance (behavioral) addictions?', '["No", "Yes, only one: Gambling Disorder", "Yes, gaming and sex", "None"]', 1, 'Internet Gaming Disorder is in the appendix for further study. (MGH Pocket)'),
    (v_topic_id, '272: Gambling Disorder is characterized by:', '["Winning money", "Chasing losses, needing to gamble with increasing amounts of money to achieve excitement, lying about gambling", "None", "None"]', 1, 'Activates the same reward pathways as drugs. (Kaplan & Sadock)'),
    (v_topic_id, '273: Treatment for Gambling Disorder?', '["Lithium", "CBT, Gamblers Anonymous (12-step), and off-label Naltrexone to reduce urges", "SSRIs only", "None"]', 1, 'High suicide risk due to financial ruin. (First Aid)'),
    (v_topic_id, '274: Which medication class is known to trigger pathological gambling as a side effect?', '["SSRIs", "Dopamine agonists (e.g., Pramipexole, Ropinirole) used for Parkinson''s or Restless Legs Syndrome", "Benzos", "None"]', 1, 'Also Aripiprazole (partial D2 agonist). (MGH Pocket)'),
    (v_topic_id, '275: SBIRT stands for:', '["A drug", "Screening, Brief Intervention, and Referral to Treatment", "None", "None"]', 1, 'Public health approach to early intervention in primary care. (Kaplan & Sadock)'),
    (v_topic_id, '276: Drug craving is most strongly driven by which psychological concept?', '["Classical conditioning (environmental cues like seeing a needle trigger the dopamine response)", "Operant conditioning", "None", "None"]', 0, 'Why patients must "change their playmates, playgrounds, and playthings." (First Aid)'),
    (v_topic_id, '277: What is "PAWS" (Post-Acute Withdrawal Syndrome)?', '["A dog", "Prolonged symptoms (anxiety, sleep issues, anhedonia) lasting months after acute withdrawal resolves", "None", "None"]', 1, 'Major cause of late relapse. (MGH Pocket)'),
    (v_topic_id, '278: Nicotine and Schizophrenia?', '["Low use", "Extremely high smoking rates (>80%); nicotine may temporarily improve cognitive deficits via alpha-7 receptors", "None", "None"]', 1, 'Self-medication hypothesis. (Kaplan & Sadock)'),
    (v_topic_id, '279: Electronic cigarettes (Vaping)?', '["Safe", "Deliver nicotine without tar/combustion, but carry risks of EVALI (E-cigarette or Vaping Use-Associated Lung Injury) and highly addictive for youth", "None", "None"]', 1, 'EVALI was linked to Vitamin E acetate in THC vapes. (First Aid)'),
    (v_topic_id, '280: Anosmia (loss of smell) can be caused by chronic snorting of:', '["Heroin", "Cocaine", "Meth", "None"]', 1, 'Destroys olfactory nerves. (MGH Pocket)'),
    (v_topic_id, '281: Opioids effect on testosterone?', '["Increases it", "Chronic opioid use causes severe opioid-induced endocrinopathy (hypogonadism, low libido, fatigue)", "None", "None"]', 1, 'Often overlooked side effect. (Kaplan & Sadock)'),
    (v_topic_id, '282: Prescription drug abuse demographic shift?', '["Only in cities", "Massive rise in rural/suburban areas and the elderly", "None", "None"]', 1, 'Epidemiology of the opioid crisis. (First Aid)'),
    (v_topic_id, '283: Good Samaritan Laws?', '["Protect doctors", "Protect individuals from prosecution for drug possession if they call 911 to report an overdose", "None", "None"]', 1, 'Harm reduction policy. (MGH Pocket)'),
    (v_topic_id, '284: Supervised injection facilities?', '["Illegal everywhere", "Reduce overdose deaths and HIV transmission by providing a safe, medically monitored space; highly controversial in the US", "None", "None"]', 1, 'Evidence-based in Canada/Europe. (Kaplan & Sadock)'),
    (v_topic_id, '285: Can a pregnant woman use nicotine patches?', '["No", "Yes, NRT is generally considered safer than smoking during pregnancy, though not entirely risk-free", "None", "None"]', 1, 'Harm reduction. (First Aid)'),
    (v_topic_id, '286: Highest mortality rate of any psychiatric illness?', '["Schizophrenia", "Anorexia Nervosa, followed closely by Substance Use Disorders (Opioids)", "None", "None"]', 1, 'Addiction is a terminal disease if untreated. (MGH Pocket)'),
    (v_topic_id, '287: Urine drug screen tampering?', '["Bleach or drinking excessive water (which lowers specific gravity and creatinine)", "None", "None", "None"]', 0, 'Always check temperature and creatinine of the sample. (Kaplan & Sadock)'),
    (v_topic_id, '288: Fentanyl analogs (e.g., Acetylfentanyl) on standard UDS?', '["Always positive", "Often test NEGATIVE on standard opiate screens because they lack the morphine ring structure", "None", "None"]', 1, 'Must order a specific fentanyl assay. (First Aid)'),
    (v_topic_id, '289: Kratom withdrawal?', '["None", "Similar to mild opioid withdrawal (runny nose, aches, irritability)", "None", "None"]', 1, 'Treated symptomatically or with buprenorphine. (MGH Pocket)'),
    (v_topic_id, '290: Tianeptine?', '["Antidepressant", "An atypical antidepressant sold as a supplement (''gas station heroin''); has mu-opioid agonist effects and causes severe withdrawal", "None", "None"]', 1, 'Emerging drug of abuse. (Kaplan & Sadock)'),
    (v_topic_id, '291: Poppers (Amyl nitrite)?', '["Stimulant", "Inhalant used to enhance sexual pleasure; causes rapid vasodilation (hypotension, flushing, headache)", "None", "None"]', 1, 'Fatal if combined with PDE5 inhibitors (Viagra). (First Aid)'),
    (v_topic_id, '292: Huffing Freon (refrigerant)?', '["Safe", "Can cause sudden death or severe frostbite to the airway", "None", "None"]', 1, 'Inhalant abuse. (MGH Pocket)'),
    (v_topic_id, '293: Are drug-seeking patients usually cooperative?', '["Yes", "Often manipulative, demanding, or hostile due to the neurobiology of addiction overriding normal social norms", "None", "None"]', 1, 'Requires firm, objective boundaries from the physician. (Kaplan & Sadock)'),
    (v_topic_id, '294: The "Addictive Personality"?', '["A DSM diagnosis", "Not a validated psychiatric diagnosis; addiction affects all personality types", "None", "None"]', 1, 'Antisocial traits do increase risk, however. (First Aid)'),
    (v_topic_id, '295: Iatrogenic addiction?', '["Addiction caused by doctors", "Addiction developing from properly prescribed medical treatment; relatively rare if screening is done properly", "None", "None"]', 1, 'Most opioid abusers start with diverted prescriptions. (MGH Pocket)'),
    (v_topic_id, '296: Does treating ADHD with stimulants in childhood increase the risk of substance abuse later?', '["Yes", "No, it actually REDUCES the risk of future substance abuse by adequately treating the impulsivity", "None", "None"]', 1, 'A common myth busted. (Kaplan & Sadock)'),
    (v_topic_id, '297: Methadone is a full agonist. Buprenorphine is a partial agonist. Naltrexone is an antagonist. Which has the highest overdose risk?', '["Naltrexone", "Methadone", "Buprenorphine", "None"]', 1, 'Requires strict monitoring. (First Aid)'),
    (v_topic_id, '298: Which of the MAT drugs can be prescribed in a regular doctor''s office?', '["Methadone", "Buprenorphine and Naltrexone", "None", "None"]', 1, 'Expands access. (MGH Pocket)'),
    (v_topic_id, '299: Summary: Pinpoint pupils + Coma + Slow breathing = ?', '["Heroin/Opioid Overdose -> Give Naloxone", "Cocaine OD", "None", "None"]', 0, 'Classic ER triad. (Kaplan & Sadock)'),
    (v_topic_id, '300: Final Pearl: Addiction is defined by?', '["Physical dependence", "Compulsive use DESPITE NEGATIVE CONSEQUENCES", "None", "None"]', 1, 'The core definition of a Substance Use Disorder. (MediHelp Mastery)');

END $$;

COMMIT;
